import{_ as r,a0 as d,w as f,s,I as n,x as e,a1 as o,A as i,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"用 nftwatch 监控你的 Linux 防火墙 | LCTT x X-CMD","titleTemplate":false,"description":"用 nftwatch 监控你的 Linux 防火墙 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 nftwatch 监控你的 Linux 防火墙 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 nftwatch 监控你的 Linux 防火墙 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220718 Monitor your Linux firewall with nftwatch","title":"用 nftwatch 监控你的 Linux 防火墙","tag":"202207","desc":""},"relativePath":"202207/20220718 Monitor your Linux firewall with nftwatch.md","filePath":"[post].md"}'),p={name:"202207/20220718 Monitor your Linux firewall with nftwatch.md"};function u(w,t,h,m,x,T){const l=d("Link");return f(),s("div",null,[t[24]||(t[24]=n("h1",{id:"用-nftwatch-监控你的-linux-防火墙",tabindex:"-1"},[e("用 nftwatch 监控你的 Linux 防火墙 "),n("a",{class:"header-anchor",href:"#用-nftwatch-监控你的-linux-防火墙","aria-label":"Permalink to “用 nftwatch 监控你的 Linux 防火墙”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202207/24/070724d542rvbbg3af3o9p.jpg",alt:""})],-1)),t[26]||(t[26]=n("blockquote",null,[n("p",null,"我创建了 Linux nftwatch 命令来观察防火墙的流量统计。")],-1)),n("p",null,[t[1]||(t[1]=e("Netfilter 表（",-1)),o(l,{href:"https://developers.redhat.com/blog/2016/10/28/what-comes-after-iptables-its-successor-of-course-nftables?extIdCarryOver=true&sc_cid=701f2000001OH79AAG#getting_started"},{default:i(()=>[...t[0]||(t[0]=[e("nftables",-1)])]),_:1}),t[2]||(t[2]=e("）是现代 Linux 发行版中的默认防火墙。它在 Fedora 和 RHEL 8、最新的 Debian 和许多其他版本上都有。它取代了早期发行版中捆绑的旧版 iptables。它是一个强大的、值得的 iptables 替代品，作为一个广泛使用它的人，我欣赏它的能力和功能。",-1))]),t[27]||(t[27]=a('<p>nftables 的一个特点是能够为许多元素添加计数器，例如规则。这些都是按需启用的。你需要使用 <code>counter</code> 参数，在每一行明确地要求它。我为我的防火墙中的特定规则启用了这些计数器，这使我能够看到这些规则。</p><p>这让我开始思考。我怎样才能实时查看这些计数器？一开始我尝试了 <code>watch</code>，它允许诸如刷新率之类的东西，但我不喜欢默认格式，而且它不能滚动。我发现使用 <code>head</code> 和 <code>tail</code> 以及 <code>awk</code> 也不理想，并不存在一个用户友好的解决方案。所以我自己写了一个，我想与开源社区分享。</p><h3 id="linux-上的-nftwatch-介绍" tabindex="-1">Linux 上的 nftwatch 介绍 <a class="header-anchor" href="#linux-上的-nftwatch-介绍" aria-label="Permalink to “Linux 上的 nftwatch 介绍”">​</a></h3><p>我的解决方案，我称之为 <code>nftwatch</code>，做了几件事：</p><ul><li>它对 nftables 的输出进行重新排序和改写，使其更具有可读性。</li><li>它允许向上或向下滚动输出。</li><li>可以由用户定义的刷新率（可以实时改变）。</li><li>它可以暂停显示。</li></ul><p>你得到的不是一个表格的转储，而是显示每个规则活动的输出。</p><p><img src="https://opensource.com/sites/default/files/2022-07/nftwatch-sample.png" alt="Image of nftwatch"></p>',7)),n("p",null,[t[4]||(t[4]=e("你可以从它的 ",-1)),o(l,{href:"https://github.com/flyingrhinonz/nftwatch"},{default:i(()=>[...t[3]||(t[3]=[e("Git 仓库",-1)])]),_:1}),t[5]||(t[5]=e("下载它。",-1))]),t[28]||(t[28]=a('<p>它是 100% 的 Python 代码，100% 的开源，100% 的免费。它满足了所有免费的高质量程序的要求。</p><h3 id="在-linux-上安装-nftwatch" tabindex="-1">在 Linux 上安装 nftwatch <a class="header-anchor" href="#在-linux-上安装-nftwatch" aria-label="Permalink to “在 Linux 上安装 nftwatch”">​</a></h3><p>以下是手动安装说明：</p><ol><li>克隆或从 git 仓库下载该项目。</li><li>将 <code>nftwatch.yml</code> 复制到 <code>/etc/nftwatch.yml</code>。</li><li>将 <code>nftwatch</code> 复制到 <code>/usr/local/bin/nftwatch</code> 并使用 <code>chmod a+x</code> 授予其可执行权限。</li><li>使用 <code>nftwatch</code>，不带任何参数来运行它。</li><li>参见 <code>nftwatch -m</code> 的手册。</li></ol>',4)),n("p",null,[t[7]||(t[7]=e("你也可以在没有 ",-1)),o(l,{href:"https://opensource.com/article/21/9/yaml-cheat-sheet"},{default:i(()=>[...t[6]||(t[6]=[e("YAML",-1)])]),_:1}),t[8]||(t[8]=e(" 配置文件的情况下运行 nftwatch，在这种情况下它使用内置的默认值。",-1))]),t[29]||(t[29]=a('<h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p><code>nftwatch</code> 命令显示 nftables 规则。大多数控制都是为此目的而设计的。</p><p>箭头键和等效的 Vim 的按键控制滚动。使用 <code>F</code> 或 <code>S</code> 键来改变刷新速度。使用 <code>P</code> 键来暂停显示。</p><p>运行 <code>nftwatch -m</code> 以获得完整的说明，以及交互式按键控制的列表。</p><h3 id="防火墙的新观点" tabindex="-1">防火墙的新观点 <a class="header-anchor" href="#防火墙的新观点" aria-label="Permalink to “防火墙的新观点”">​</a></h3><p>即使你花费了时间去配置防火墙，它也会显得晦涩难懂和模糊不清。除了从日志条目中推断指标外，很难判断你的防火墙实际看到的活动类型。 使用 <code>nftwatch</code>，你可以看到你的防火墙在工作，并且可以更好地了解你的网络每天需要处理的流量类型。</p><p><em>（文内图片来自 Kenneth Aaron，CC BY-SA 4.0）</em></p><hr>',8)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),o(l,{href:"https://opensource.com/article/22/7/nftwatch-linux-firewall"},{default:i(()=>[...t[9]||(t[9]=[e("https://opensource.com/article/22/7/nftwatch-linux-firewall",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("作者：",-1)),o(l,{href:"https://opensource.com/users/flyingrhino"},{default:i(()=>[...t[11]||(t[11]=[e("Kenneth Aaron",-1)])]),_:1}),t[16]||(t[16]=e(" 选题：",-1)),o(l,{href:"https://github.com/lkxed"},{default:i(()=>[...t[12]||(t[12]=[e("lkxed",-1)])]),_:1}),t[17]||(t[17]=e(" 译者：",-1)),o(l,{href:"https://github.com/geekpi"},{default:i(()=>[...t[13]||(t[13]=[e("geekpi",-1)])]),_:1}),t[18]||(t[18]=e(" 校对：",-1)),o(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原创编译，",-1)),o(l,{href:"https://linux.cn/"},{default:i(()=>[...t[20]||(t[20]=[e("Linux中国",-1)])]),_:1}),t[23]||(t[23]=e(" 荣誉推出",-1))])])}const g=r(p,[["render",u]]);export{L as __pageData,g as default};
